import importlib.util
import sys
import tempfile
import unittest
from pathlib import Path

SCRIPT = Path(__file__).resolve().parents[2] / "main/resources/assistant/source_outline.py"
# This contract imports a packaged resource; keep generated bytecode out of the jar.
sys.dont_write_bytecode = True
spec = importlib.util.spec_from_file_location("source_outline", SCRIPT)
module = importlib.util.module_from_spec(spec)
spec.loader.exec_module(module)


class SourceOutlineContract(unittest.TestCase):
    def test_pinned_languages_symbols_references_and_syntax_gaps(self):
        fixtures = {"python": ("def greet():\n    return greet()\n", "greet"),
                    "java": ("class Hello { void greet() { greet(); } }", "greet"),
                    "javascript": ("function greet() { greet(); }", "greet"),
                    "typescript": ("function greet(): void { greet(); }", "greet"),
                    "tsx": ("function greet() { return <div/>; }", "greet")}
        with tempfile.TemporaryDirectory() as directory:
            path = Path(directory) / "fixture"
            for language, (source, symbol) in fixtures.items():
                path.write_text(source)
                outline = module.analyze(str(path), language, "outline", "")
                self.assertFalse(outline["syntax_errors"], language)
                self.assertTrue(outline["approximate"])
                self.assertTrue(any(entry["name"] == symbol for entry in outline["entries"]), language)
                symbols = module.analyze(str(path), language, "symbols", "gree")
                self.assertEqual(symbol, symbols["entries"][0]["name"])
                if language != "tsx":
                    references = module.analyze(str(path), language, "references", symbol)
                    self.assertEqual(1, len(references["entries"]), language)
                    self.assertEqual(symbol, references["entries"][0]["enclosing"])
            path.write_text("def invalid(:")
            self.assertTrue(module.analyze(str(path), "python", "outline", "")["syntax_errors"])
            path.write_text("\n".join(f"def f{i}(): pass" for i in range(150)))
            limited = module.analyze(str(path), "python", "outline", "")
            self.assertEqual(100, len(limited["entries"]))
            self.assertTrue(limited["truncated"])


if __name__ == "__main__":
    unittest.main()
